import pathlib,json,subprocess,hashlib
P=pathlib.Path(__file__).parent;SESSION='mangrove-menu-items-preview-context-tag';BASE=json.loads((P/'server.json').read_text())['url'];CAP=P/'captures';CAP.mkdir(exist_ok=True)
def call(*args,script=None):
 c=['agent-browser','--session',SESSION,*args];r=subprocess.run(c,input=script,text=True,capture_output=True)
 if r.returncode:
  if args and args[0]=='open' and 'Operation timed out' in (r.stdout+r.stderr):
   observed=subprocess.run(['agent-browser','--session',SESSION,'get','url'],text=True,capture_output=True,check=True).stdout.strip()
   assert observed==args[1],(observed,args[1])
   with (P/'navigation-timeout-observations.log').open('a') as log:log.write(json.dumps({'requestedURL':args[1],'observedURL':observed,'error':r.stdout+r.stderr,'continuedOnlyToIndependentContextAndFontsCapture':True})+'\n')
  else:raise RuntimeError(str(c)+r.stdout+r.stderr)
 return r.stdout
def evaluate(s):
 r=json.loads(call('eval','--stdin','--json',script=s));assert r['success'],r;return r['data']['result']
SCRIPT="""document.fonts.ready.then(()=>new Promise(resolve=>setTimeout(()=>{const fields=['display','fontFamily','fontSize','fontWeight','fontStyle','lineHeight','letterSpacing','color','backgroundColor','borderBottomWidth','borderBottomStyle','borderBottomColor','paddingBottom','textDecorationLine','textDecorationColor','textUnderlineOffset','outlineWidth','outlineStyle','outlineColor','outlineOffset','boxShadow','cursor','direction','whiteSpace','overflow','marginTop','marginBottom','paddingLeft','paddingRight','listStyleType'];const rect=r=>({x:r.x,y:r.y,width:r.width,height:r.height});const node=e=>({tag:e.tagName,html:e.outerHTML,box:rect(e.getBoundingClientRect()),fragments:[...e.getClientRects()].map(rect),computed:Object.fromEntries(fields.map(f=>[f,getComputedStyle(e)[f]]))});const anchors=[...document.querySelectorAll('.menu li a')].map(e=>{const range=document.createRange();range.selectNodeContents(e);return {...node(e),owner:e.parentElement.dataset.menuOwner,text:e.textContent,href:e.getAttribute('href'),tabIndex:e.getAttribute('tabindex'),class:e.className,hover:e.matches(':hover'),focus:e.matches(':focus'),focusVisible:e.matches(':focus-visible'),textFragments:[...range.getClientRects()].map(rect),li:node(e.parentElement)};});resolve({previewContext:{bodyClasses:[...document.body.classList],canvasLang:document.getElementById('storybook-root').lang,canvasDir:document.getElementById('storybook-root').dir,i18n:window.menuLocaleObservation,UNDRR:window.UNDRR,bodyInteractive:getComputedStyle(document.body).getPropertyValue('--mg-color-interactive')},url:location.href,lang:document.documentElement.lang,dir:document.documentElement.dir,viewport:{width:innerWidth,height:innerHeight,dpr:devicePixelRatio},arguments:window.menuFixture.arguments(),menu:node(document.querySelector('.menu')),anchors,fonts:[...document.fonts].filter(f=>f.status==='loaded').map(f=>({family:f.family,weight:f.weight,style:f.style,stretch:f.stretch,status:f.status})),fontResources:performance.getEntriesByType('resource').filter(r=>/woff/.test(r.name)).map(r=>({url:r.name,duration:r.duration,transferSize:r.transferSize,decodedBodySize:r.decodedBodySize})),roleTokens:Object.fromEntries(['--mg-font-family-text','--mg-font-size-100','--mg-font-size-200','--mg-color-neutral-600','--mg-color-red-900','--mg-spacing-25','--mg-color-focus-ring','--mg-focus-ring-width','--mg-focus-ring-offset'].map(k=>[k,getComputedStyle(document.documentElement).getPropertyValue(k)]))});},350)))"""
manifest=[]
def capture(brand,script,width,state):
 data=evaluate(SCRIPT);expectedClass=[] if brand=='undrr' else ['mg-theme-'+brand];assert data['previewContext']['bodyClasses']==expectedClass;assert data['previewContext']['i18n']['locale']==('ar' if script=='arabic' else 'en');assert data['previewContext']['i18n']['direction']==('rtl' if script=='arabic' else 'ltr');assert len(data['anchors'])==2;assert [a['class'] for a in data['anchors']]==['','selected'];name=f'{brand}-{script}-{width}-{state}';raw=json.dumps(data,ensure_ascii=False,indent=2).encode();(CAP/(name+'.json')).write_bytes(raw);call('screenshot',str(CAP/(name+'.png')));manifest.append({'case':name,'brand':brand,'script':script,'width':width,'state':state,'json':{'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()},'png':{'bytes':(CAP/(name+'.png')).stat().st_size,'sha256':hashlib.sha256((CAP/(name+'.png')).read_bytes()).hexdigest()}});return data
for brand in ['undrr','delta','irp','mcr','preventionweb']:
 for script in ['english','arabic']:
  for width in [390,1164]:
   url=BASE+'/?brand='+brand+'&script='+script;call('set','viewport',str(width),'420','1');call('open',url);call('mouse','move','1','410');r=capture(brand,script,width,'initial')
   for index,state in [(0,'hover-default'),(1,'hover-selected')]:
    b=r['anchors'][index]['fragments'][0];call('mouse','move',str(round(b['x']+b['width']/2)),str(round(b['y']+b['height']/2)));capture(brand,script,width,state)
   call('mouse','move','1','410');call('open',url);call('press','Tab');capture(brand,script,width,'focus-default');call('press','Tab');capture(brand,script,width,'focus-selected')
   text='Additional information about disaster risk reduction and community resilience, preserved as caller supplied logical copy.' if script=='english' else 'معلومات إضافية حول الحد من مخاطر الكوارث وبناء قدرة المجتمعات على الصمود، مع الحفاظ على النص الذي يقدمه المستهلك.'
   evaluate('window.menuFixture.updateText('+json.dumps(text)+'); true');r=capture(brand,script,width,'caller-copy-update');assert all(a['text']==text for a in r['anchors'])
   (P/'capture-progress.json').write_text(json.dumps({'completeCases':len(manifest),'lastCase':manifest[-1]['case']})+'\n');print(manifest[-1]['case'],flush=True)
(P/'capture-manifest.json').write_text(json.dumps({'controlledActualJSXFixture':True,'authoredStory':False,'cases':manifest,'nativeAccepted':False},indent=2)+'\n');call('close');print('Completed',len(manifest),'captures',flush=True)
